<?php admin_component('catalog-nav',['catalogSection'=>$entity]); $manage=$capabilities[$entity.'.manage']??false; ?>
<section class="admin-page-head"><div><p class="admin-kicker">CATÁLOGO</p><h1><?= e($heading) ?></h1><p><?= e($description) ?></p></div><?php if($manage):?><a class="admin-primary-button" href="/admin/<?= e($entity) ?>/create">+ Nuevo registro</a><?php endif?></section>
<form class="admin-panel admin-filter-bar" method="get" action="/admin/<?= e($entity) ?>"><label class="admin-field"><span>Buscar</span><input type="search" name="q" maxlength="120" value="<?= e($q) ?>" placeholder="Clave o nombre"></label><label class="admin-field"><span>Estado</span><select name="status"><option value="all" <?= $status==='all'?'selected':'' ?>>Todos</option><option value="active" <?= $status==='active'?'selected':'' ?>>Activos</option><option value="inactive" <?= $status==='inactive'?'selected':'' ?>>Inactivos</option></select></label><button class="admin-secondary-button" type="submit">Aplicar filtros</button></form>
<section class="admin-panel admin-table-panel"><?php if($page->items===[]):?><div class="admin-empty"><strong>No hay registros para mostrar.</strong><span>Prueba con otros filtros o crea el primer registro autorizado.</span></div><?php else:?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Clave y nombre</th><th><?= $entity==='categories'?'Categoría superior':'Descripción' ?></th><th>Estado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody><?php foreach($page->items as $item):?><tr><td><strong><?= e($item['name']) ?></strong><small><?= e($item['code']) ?></small></td><td><?= e($entity==='categories'?($item['parent_name']??'Nivel principal'):($item['description']??'Sin descripción')) ?></td><td><span class="admin-status <?= (int)$item['is_active']===1?'is-active':'' ?>"><?= (int)$item['is_active']===1?'Activo':'Inactivo' ?></span></td><td class="admin-actions"><?php if($manage):?><a class="admin-secondary-button" href="/admin/<?= e($entity) ?>/edit?id=<?= e($item['id']) ?>">Editar</a><form method="post" action="/admin/<?= e($entity) ?>/status"><input type="hidden" name="_token" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= e($item['id']) ?>"><input type="hidden" name="active" value="<?= (int)$item['is_active']===1?'0':'1' ?>"><button class="admin-quiet-button" type="submit" data-confirm="¿Confirmas el cambio de estado?"><?= (int)$item['is_active']===1?'Desactivar':'Activar' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?php $base=http_build_query(['q'=>$q,'status'=>$status]);?><div class="admin-pagination"><?php if($page->offset>0):?><a href="?<?= e($base.'&offset='.max(0,$page->offset-$page->limit)) ?>">Anterior</a><?php endif?><?php if($page->hasMore):?><a href="?<?= e($base.'&offset='.($page->offset+$page->limit)) ?>">Siguiente</a><?php endif?></div></section>
